function parseArgs(argv, opts){
  opts=opts||{};
  var result={options:{}, flags:{}, positionals:[]};
  var i=opts.skipFirst?1:0;
  for(; i<argv.length; i++){
    var a=String(argv[i]);
    if(a.indexOf('--')===0){
      var body=a.slice(2);
      if(body.indexOf('no-')===0){ result.flags[body.slice(3)]=false; continue; }
      if(body.indexOf('=')>=0){ var kv=body.split('='); result.options[kv[0]]=kv.slice(1).join('='); continue; }
      if(i+1<argv.length && String(argv[i+1]).indexOf('-')!==0){ result.options[body]=String(argv[i+1]); i++; }
      else { result.flags[body]=true; }
    } else if(a.indexOf('-')===0 && a.length>1){
      var shorts=a.slice(1).split('');
      for(var s=0;s<shorts.length;s++){ result.flags[shorts[s]]=true; }
    } else { result.positionals.push(a); }
  }
  return result;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { parseArgs:parseArgs };
}
if (typeof window !== 'undefined') {
  window.ArgForgePure = { parseArgs:parseArgs };
}
